formData.jsFunction:
def addError(response, key, msg) {
    if (response[key] == null) response[key] = msg
    else if (response[key] instanceof List) response[key] << msg
    else response[key] = [response[key], msg]
}

def validate(request, response = [:]) {
    if (!request) {
        return response
    }
    def columns = request.columns ?: []
    if (columns.size() == 0) {
        addError(response, "columns", "No columns are selected.")
        return response
    } else if (columns.size() == 1) {
        if (columns[0]?.hidden) {
            addError(response, "columns", "Please select atleast one unhidden column to generate report.")
            return response
        }
    }
    return response
}
